export const BODY: string = "\n<p>سیچوریشن رنگوں کی شدت ہے: کم سیچوریشن تصویر کو مدھم اور بھورا کر دیتی ہے، زیادہ سیچوریشن رنگوں کو گہرا اور توانا بنا دیتی ہے۔</p>\n<p>کیمرا اکثر وہ رنگ نہیں پکڑتا جو آنکھ دیکھتی ہے، خاص طور پر ابر آلود دن یا مصنوعی روشنی میں۔ سیچوریشن کا ہلکا سا اضافہ تصویر کو وہ زندگی واپس دے دیتا ہے جو کیمرے نے کھو دی تھی۔</p>\n<p>یہ رہنما سلائیڈر، پہلے سے طے شدہ سیٹنگز، جلد کے رنگ، کھانے اور مصنوعات کی تصویروں، اور قدرتی رنگ کا طریقہ بتاتا ہے۔ ایڈٹ کرنے کے لیے <a href=\"/ur/tasveer-ki-saturation-badlein/\">امیج سیچوریشن ایڈیٹر</a> کھولیں۔</p>\n<h2 id=\"what-saturation-does\">سیچوریشن اصل میں کیا کرتی ہے</h2>\n<p>سیچوریشن ہر رنگ کی خالصیت بدلتی ہے: صفر پر تصویر سیاہ سفید ہو جاتی ہے، اور سو فیصد پر رنگ اپنی انتہا پر پہنچ جاتے ہیں۔ درمیان میں قدرتی رنگ ملتے ہیں۔</p>\n<p>سیچوریشن روشنی نہیں بدلتی، صرف رنگ کی گہرائی بدلتی ہے۔ اسی لیے مدھم تصویر میں سیچوریشن بڑھانے سے رنگ توانا ہوتے ہیں، مگر تاریک حصے روشن نہیں ہوتے۔</p>\n<h2 id=\"why-photos-look-dull\">تصویریں مدھم کیوں نکلتی ہیں</h2>\n<p>ابر آلود موسم میں روشنی پھیلی ہوئی ہوتی ہے، جس سے رنگ مدھم ہو جاتے ہیں۔ مصنوعی روشنی میں بھی کیمرا رنگوں کو درست نہیں پکڑتا، خاص طور پر فلوروسینٹ بلب کے نیچے۔</p>\n<p>فون کیمرے اکثر رنگوں کو خود ہی نرم کر دیتے ہیں، تاکہ تصویر قدرتی لگے۔ نتیجہ یہ ہوتا ہے کہ اصلی منظر سے زیادہ مدھم تصویر بنتی ہے، جسے ہلکی ایڈیٹنگ سے ٹھیک کیا جا سکتا ہے۔</p>\n<h2 id=\"slider-explained\">سیچوریشن سلائیڈر کی وضاحت</h2>\n<p>سلائیڈر کو دائیں کھسکانے سے رنگ گہرے ہوتے ہیں، بائیں کھسکانے سے مدھم ہوتے ہیں۔ چھوٹی تبدیلی، جیسے دس سے بیس فیصد اضافہ، اکثر کافی ہوتی ہے۔</p>\n<p>سلائیڈر کو آہستہ کھسکائیں اور ہر قدم پر تصویر دیکھیں۔ اچانک بڑا اضافہ رنگوں کو غیر فطری کر دیتا ہے، خاص طور پر جلد اور آسمان میں۔</p>\n<h2 id=\"quick-presets\">ایک کلک والے رنگ کے پری سیٹ</h2>\n<p>پری سیٹ تیار شدہ سیٹنگز ہیں، جیسے توانا، نرم، مدھم اور سیاہ سفید۔ ایک کلک میں تصویر کا رنگ مزاج بدل جاتا ہے، بغیر سلائیڈر کھسکائے۔</p>\n<p>پری سیٹ شروعات کے لیے اچھے ہیں، مگر ہر تصویر پر ایک جیسے نہیں چلتے۔ پری سیٹ لگانے کے بعد سلائیڈر سے تھوڑی تبدیلی کر کے اسے اپنی تصویر کے مطابق ڈھالیں۔</p>\n<h2 id=\"muted-vs-grayscale\">مدھم بمقابلہ گرے اسکیل: رنگ ہٹانے کے دو طریقے</h2>\n<p>مدھم کرنے سے رنگ ہلکے ہو جاتے ہیں مگر مکمل ختم نہیں ہوتے، جس سے تصویر نرم اور خوبصورت لگتی ہے۔ گرے اسکیل رنگ مکمل ہٹا کر سیاہ سفید تصویر بنا دیتا ہے۔</p>\n<p>مدھم انداز شادی اور فیشن کی تصویروں میں اچھا لگتا ہے، جبکہ گرے اسکیل ڈرامائی اور دستاویزی احساس دیتا ہے۔ دونوں کا مقصد الگ ہے، اس لیے تصویر کے مزاج کے مطابق چنیں۔</p>\n<h2 id=\"hyper-saturation\">بہت زیادہ سیچوریشن: جب زیادہ بہت زیادہ ہو جائے</h2>\n<p>بہت زیادہ سیچوریشن سے رنگ چیختے ہیں: گھاس نیون سبز، جلد نارنجی اور آسمان گہرا نیلا ہو جاتا ہے۔ تصویر کارٹون جیسی لگنے لگتی ہے۔</p>\n<p>حد سے زیادہ کی نشانی یہ ہے کہ ایک رنگ دوسروں پر حاوی ہو جائے۔ اگر گھاس آنکھ کو چبھے تو سلائیڈر واپس کھسکائیں، کیونکہ قدرتی رنگ ہمیشہ بہتر لگتے ہیں۔</p>\n<h2 id=\"saturation-and-skin\">سیچوریشن اور جلد کے رنگ</h2>\n<p>جلد سیچوریشن کے لیے سب سے حساس حصہ ہے: تھوڑا سا اضافہ بھی جلد کو نارنجی یا سرخ کر دیتا ہے۔ پورٹریٹ میں سیچوریشن ہمیشہ ہلکی رکھیں۔</p>\n<p>اگر جلد نارنجی لگنے لگے تو سیچوریشن کم کرنے کے بجائے وائبرینس آزمائیں، جو جلد کو کم متاثر کرتی ہے۔ چہرے کو زوم کر کے جانچنا بہتر ہے۔</p>\n<h2 id=\"saturation-for-landscapes\">مناظر کے لیے سیچوریشن</h2>\n<p>مناظر میں سیچوریشن آسمان اور ہریالی کو گہرا کرتی ہے، جس سے تصویر توانا لگتی ہے۔ پہاڑوں اور سمندر کی تصویر میں درمیانہ اضافہ اچھا رہتا ہے۔</p>\n<p>لیکن منظر میں بھی حد ہے: زیادہ سبز گھاس غیر فطری لگتی ہے۔ شدت کو اس حد تک رکھیں کہ منظر خوبصورت لگے، مگر اصلی بھی رہے۔</p>\n<h2 id=\"saturation-for-food\">کھانے کی تصویروں کے لیے سیچوریشن</h2>\n<p>کھانے کی تصویر میں سیچوریشن بھوک بڑھاتی ہے: سرخ ٹماٹر گہرے، سبز سلاد تازہ اور سنہری روٹی مزیدار لگتی ہے۔ کھانے میں تھوڑا زیادہ اضافہ بھی اچھا لگتا ہے۔</p>\n<p>لیکن سفید پلیٹ اور میز کے کپڑے پر نظر رکھیں: اگر سفید حصہ رنگین لگنے لگے تو سیچوریشن بہت زیادہ ہے۔ کھانا توانا ہونا چاہیے، پلیٹ نہیں۔</p>\n<h2 id=\"saturation-for-products\">مصنوعات کی تصویروں کے لیے سیچوریشن</h2>\n<p>مصنوعات کی تصویر میں رنگ درست ہونا چاہیے، کیونکہ خریدار اسی رنگ کی توقع کرتا ہے۔ زیادہ سیچوریشن مصنوعات کا رنگ بدل دیتی ہے اور واپسی کا سبب بنتی ہے۔</p>\n<p>مصنوعات کے لیے سیچوریشن کم رکھیں اور اصل رنگ سے ملا کر دیکھیں۔ خوبصورتی سے زیادہ درستگی اہم ہے، کیونکہ غلط رنگ خریدار کو مایوس کرتا ہے۔</p>\n<h2 id=\"desaturating-photos\">مدھم اور خوبصورت انداز کے لیے رنگ ہٹانا</h2>\n<p>رنگ ہٹانے سے تصویر نرم اور خوبصورت لگتی ہے، جو فیشن اور شادی کی تصویروں میں مقبول ہے۔ مدھم انداز میں رنگ ہلکے ہوتے ہیں، مگر مکمل ختم نہیں ہوتے۔</p>\n<p>مدھم کرنے کے لیے سیچوریشن کو بیس سے چالیس فیصد کم کریں۔ اگر تصویر بہت بھوری لگنے لگے تو تھوڑا رنگ واپس لائیں، تاکہ زندگی باقی رہے۔</p>\n<h2 id=\"saturation-and-brightness\">سیچوریشن، روشنی اور محسوس شدہ روشنی</h2>\n<p>سیچوریشن بڑھانے سے تصویر روشن محسوس ہوتی ہے، حالانکہ اصل روشنی نہیں بدلتی۔ گہرے رنگ آنکھ کو روشن لگتے ہیں، اس لیے تصویر توانا محسوس ہوتی ہے۔</p>\n<p>اسی لیے تاریک تصویر میں سیچوریشن بڑھانا روشنی کا متبادل نہیں۔ پہلے روشنی درست کریں، پھر رنگ، ورنہ تاریک حصے رنگین مگر پھر بھی تاریک رہیں گے۔</p>\n<h2 id=\"formats-and-export\">فارمیٹ اور برآمد</h2>\n<p>ایڈٹ کے بعد تصویر کو اسی فارمیٹ میں محفوظ کریں جس میں وہ تھی، تاکہ شفافیت یا معیار نہ بدلے۔ PNG شفافیت بچاتا ہے، JPG چھوٹی فائل دیتا ہے۔</p>\n<p>برآمد سے پہلے نتیجہ کو مکمل سائز میں دیکھیں، کیونکہ چھوٹے پیش منظر پر رنگ ہلکے لگتے ہیں۔ اصل فائل بھی محفوظ رکھیں، تاکہ دوبارہ ایڈٹ کر سکیں۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: بغیر اپ لوڈ کے ایڈیٹنگ</h2>\n<p>ایڈیٹنگ آپ کے براؤزر میں ہوتی ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ نجی اور خاندانی تصویروں کے لیے بہت اہم ہے، کیونکہ فائل آپ کے آلے سے باہر نہیں نکلتی۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی نقل محفوظ نہیں رہتی۔</p>\n<h2 id=\"common-mistakes\">سیچوریشن بدلتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی سلائیڈر کو آخر تک کھسکانا ہے، جس سے رنگ غیر فطری ہو جاتے ہیں۔ دوسری غلطی جلد کو دیکھے بغیر پوری تصویر پر ایک ہی اضافہ کرنا ہے۔</p>\n<p>تیسری غلطی خراب روشنی کو سیچوریشن سے ٹھیک کرنے کی کوشش ہے۔ پہلے روشنی درست کریں، پھر رنگ، ورنہ نتیجہ کبھی قدرتی نہیں ہوگا۔</p>\n<h2 id=\"saturation-workflow\">قدرتی رنگ کا طریقہ</h2>\n<p>پہلے تصویر کو اصل حالت میں دیکھیں اور فیصلہ کریں کہ کون سے رنگ مدھم ہیں۔ پھر سیچوریشن کو تھوڑا بڑھائیں، جلد اور آسمان جانچیں، اور ضرورت ہو تو تھوڑا کم کریں۔</p>\n<p>آخر میں تصویر کو چند منٹ کے لیے چھوڑ کر دوبارہ دیکھیں۔ تازہ آنکھ سے غلطی فوراً نظر آتی ہے، جو مسلسل دیکھنے پر چھپ جاتی ہے۔</p>\n<h2 id=\"saturation-for-weddings\">شادی کی تصویروں کے لیے سیچوریشن</h2>\n<p>شادی کی تصویروں میں رنگ نرم اور گرم ہونے چاہییں: پھول توانا، کپڑے روشن اور جلد قدرتی۔ ہلکی سیچوریشن اور گرم درجہ حرارت شادی کا احساس بڑھاتے ہیں۔</p>\n<p>شادی کے البم میں سب تصویروں پر ایک ہی سیٹنگ رکھیں، تاکہ البم یکساں لگے۔ ہر تصویر پر الگ رنگ البم کو بے ترتیب بنا دیتا ہے۔ سیچوریشن اور وائبرینس کا فرق <a href=\"/ur/blog/saturation-vs-vibrance/\">سیچوریشن بمقابلہ وائبرینس</a> میں اور ایڈٹ کرنے کے عملی مراحل <a href=\"/ur/blog/tasveer-ki-saturation-kaise-badlein/\">تصویر کی سیچوریشن کیسے بدلیں</a> میں دیکھیں۔ فلٹر کے لیے <a href=\"/ur/tasveer-filters/\">امیج فلٹرز</a> استعمال کریں۔</p>\n";

